import { z } from "zod";
// TODO: either label or icon are required
const zToken = z.object({
    label: z.string().optional(),
    action: z.string().optional(),
    icon: z.string().optional(),
});
const zBreadCrumbProps = z.object({
    items: z.array(zToken).min(1),
});
export function Breadcrumb(define) {
    return define("Breadcrumb")
        .props(zBreadCrumbProps)
        .userEvents({
        click: [z.string(), null],
    })
        .render((props) => ({
        id: props.id,
        items: props.items,
    }));
}
